// GET /api/v1/warehouse/returns (warehouse staff only)
// Same as GetReturns, but scoped to the calling staff member's warehouse -
// only returns whose order was fulfilled from that warehouse are visible,
// so Store A's staff never sees Store B's return requests.
func GetWarehouseReturns(c *gin.Context) {
	warehouseID := c.MustGet("warehouse_id").(uint)

	var returns []models.ReturnRequest
	query := database.DB.Preload("Order.User").Preload("Items.OrderItem.Product").Preload("DeliveryPartner").
		Joins("JOIN orders ON orders.id = return_requests.order_id").
		Where("orders.warehouse_id = ?", warehouseID).
		Order("return_requests.created_at DESC")

	if status := c.Query("status"); status != "" {
		query = query.Where("return_requests.status = ?", status)
	}

	if err := query.Find(&returns).Error; err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to load return requests"})
		return
	}

	type StoreReturnResponse struct {
		models.ReturnRequest
		CustomerName         string `json:"customer_name"`
		CustomerPhone        string `json:"customer_phone"`
		DeliveryPartnerName  string `json:"delivery_partner_name,omitempty"`
		DeliveryPartnerPhone string `json:"delivery_partner_phone,omitempty"`
	}
	enriched := make([]StoreReturnResponse, 0, len(returns))
	for _, r := range returns {
		dpName, dpPhone := "", ""
		if r.DeliveryPartner != nil {
			dpName = r.DeliveryPartner.Name
			dpPhone = r.DeliveryPartner.Phone
		}
		enriched = append(enriched, StoreReturnResponse{
			ReturnRequest:        r,
			CustomerName:         r.Order.User.Name,
			CustomerPhone:        r.Order.User.Phone,
			DeliveryPartnerName:  dpName,
			DeliveryPartnerPhone: dpPhone,
		})
	}
	c.JSON(http.StatusOK, gin.H{"return_requests": enriched})
}

